INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5543007, 800188, 88580, '<td valign="top">lol.  Now that''s unique.  :)  It''s nice enough right-side-up, but the upside-down POV, really makes this one shine (well, maybe shine isn''t the best choice of words for an old truck, but you know what I mean).</td>', 'lol.  Now that''s unique.  :)  It''s nice enough right-side-up, but the upside-down POV, really makes this one shine (well, maybe shine isn''t the best choice of words for an old truck, but you know what I mean).', '2009-06-24 21:36:14.000000', NULL, 1),
(5543016, 801687, 98339, '<td valign="top">quite the nice little car...is it yours...this is well done</td>', 'quite the nice little car...is it yours...this is well done', '2009-06-24 21:53:02.000000', NULL, 1),
(5543019, 801223, 98339, '<td valign="top">such a little gem...I like how the light is shining on the side of the car</td>', 'such a little gem...I like how the light is shining on the side of the car', '2009-06-24 21:55:03.000000', NULL, 1),
(5543020, 801711, 98339, '<td valign="top">this is well done...took some thought and timing...</td>', 'this is well done...took some thought and timing...', '2009-06-24 21:55:18.000000', NULL, 1),
