(5543524, 801160, 74333, '<td valign="top">this shot is great.. I love the sharpness of the car and the angle.. I think, personally, the only thing that could have made this better is a lower camera angle.. but still.. this is great! good job!</td>', 'this shot is great.. I love the sharpness of the car and the angle.. I think, personally, the only thing that could have made this better is a lower camera angle.. but still.. this is great! good job!', '2009-06-25 13:01:28.000000', NULL, 1),
(5543527, 800542, 74333, '<td valign="top">looks good but i thought this was a basic editing challenge.. this seems like a grunge effect was put into it and from what i can remember that kind of effect isn''t basic editing.. i could be wrong.. but i do like the shot.</td>', 'looks good but i thought this was a basic editing challenge.. this seems like a grunge effect was put into it and from what i can remember that kind of effect isn''t basic editing.. i could be wrong.. but i do like the shot.', '2009-06-25 13:03:32.000000', NULL, 1),
(5543529, 801411, 74333, '<td valign="top">I love the colours in this shot and the clarity of the car... a shallower depth of field could have made this a little better, the background is a little distracting but overall pretty good shot.</td>', 'I love the colours in this shot and the clarity of the car... a shallower depth of field could have made this a little better, the background is a little distracting but overall pretty good shot.', '2009-06-25 13:05:40.000000', NULL, 1),
(5543531, 800919, 74333, '<td valign="top">Great View Point on this shot! and the wide angle lens was a good choice to give that distorted effect. Great shot.</td>', 'Great View Point on this shot! and the wide angle lens was a good choice to give that distorted effect. Great shot.', '2009-06-25 13:07:19.000000', NULL, 1),
(5543533, 800416, 74333, '<td valign="top">i like the angle and the fact that you included the sky in this shot.. looks beautiful.</td>', 'i like the angle and the fact that you included the sky in this shot.. looks beautiful.', '2009-06-25 13:08:42.000000', NULL, 1),
(5543536, 801415, 74333, '<td valign="top">what a beauty!! great shot nice and clear, great angle and lens choice. Good luck on this.</td>', 'what a beauty!! great shot nice and clear, great angle and lens choice. Good luck on this.', '2009-06-25 13:10:24.000000', NULL, 1),
(5543538, 801646, 74333, '<td valign="top">wow.. stripped right down!.. the shot is a little flat though.. maybe better cropping and a different aperture choice could have helped your photo.</td>', 'wow.. stripped right down!.. the shot is a little flat though.. maybe better cropping and a different aperture choice could have helped your photo.', '2009-06-25 13:11:43.000000', NULL, 1),
