(5543540, 800432, 74333, '<td valign="top">nice shot. This is definitely and oldie. Love the bullet holes in the window hahah.</td>', 'nice shot. This is definitely and oldie. Love the bullet holes in the window hahah.', '2009-06-25 13:14:35.000000', NULL, 1),
(5543542, 801732, 74333, '<td valign="top">wow.. nice job on this, great exposure.. the only thing that gets me is the distracting background.. maybe a shallower depth of field could help.. but overall.. great shot!</td>', 'wow.. nice job on this, great exposure.. the only thing that gets me is the distracting background.. maybe a shallower depth of field could help.. but overall.. great shot!', '2009-06-25 13:15:55.000000', NULL, 1),
