(5543546, 800714, 74333, '<td valign="top">the colors are great and I like this shot!</td>', 'the colors are great and I like this shot!', '2009-06-25 13:18:13.000000', NULL, 1),
(5543547, 800890, 74333, '<td valign="top">Ohhh baby!!! nice car.. i love the color and the lack of color in this shot.. good selective colour I think it really plays a nice roll in this shot.. great job and good luck!</td>', 'Ohhh baby!!! nice car.. i love the color and the lack of color in this shot.. good selective colour I think it really plays a nice roll in this shot.. great job and good luck!', '2009-06-25 13:19:29.000000', NULL, 1),
