(5550225, 801687, 81522, '<td valign="top">Love this one...</td>', 'Love this one...', '2009-06-29 22:01:35.000000', NULL, 1),
(5550230, 801269, 81522, '<td valign="top">I''m the king of the world :)</td>', 'I''m the king of the world :)', '2009-06-29 22:02:37.000000', NULL, 1),
(5550702, 800188, 86799, '<td valign="top">not an effective gimmick, IMO.</td>', 'not an effective gimmick, IMO.', '2009-06-30 07:18:18.000000', NULL, 1),
(5550704, 801236, 86799, '<td valign="top">Rockabye, Sweet baby James.</td>', 'Rockabye, Sweet baby James.', '2009-06-30 07:21:07.000000', NULL, 1),
(5550707, 801727, 86799, '<td valign="top">This could be really great with less washout on the drop light...maybe a lower wattage or a dimmer...and more sharpness/focus.  I like the overall flavor of it, though.</td>', 'This could be really great with less washout on the drop light...maybe a lower wattage or a dimmer...and more sharpness/focus.  I like the overall flavor of it, though.', '2009-06-30 07:23:34.000000', NULL, 1),
(5550710, 801667, 86799, '<td valign="top">Nice idea.  A bit too bright on the inside roof and man''s face.</td>', 'Nice idea.  A bit too bright on the inside roof and man''s face.', '2009-06-30 07:25:42.000000', NULL, 1),
(5550991, 801591, 83313, '<td valign="top">Focus seems to be a touch more on the building than the car, but that is a minor nitpick. I like this. Gives off an impression of desolation and abandonment.<br/> <br/>Some of the focus issue I mentioned could be the result of compression artifacts. With a 109k file size, you had some more overhead to use less compression and get a little more clarity out of it.</td>', 'Focus seems to be a touch more on the building than the car, but that is a minor nitpick. I like this. Gives off an impression of desolation and abandonment. Some of the focus issue I mentioned could be the result of compression artifacts. With a 109k file size, you had some more overhead to use less compression and get a little more clarity out of it.', '2009-06-30 13:38:08.000000', NULL, 1),
(5550993, 801557, 83313, '<td valign="top">I love tailfins! Nice crusty blue. The high overhead sun is not the best for good photos, but I like this in spite of it. Perhaps a little too tight of a crop on the right for my tastes.</td>', 'I love tailfins! Nice crusty blue. The high overhead sun is not the best for good photos, but I like this in spite of it. Perhaps a little too tight of a crop on the right for my tastes.', '2009-06-30 13:40:12.000000', NULL, 1),
(5550998, 801641, 98186, '<td valign="top">Love the Mustang!  I don''t know if I''ve ever seen one that color.  I really like the fading colors in the sky.  Very cool!</td>', 'Love the Mustang!  I don''t know if I''ve ever seen one that color.  I really like the fading colors in the sky.  Very cool!', '2009-06-30 13:45:57.000000', NULL, 1),
(5551002, 801691, 98186, '<td valign="top">I like the depth of field on this one.</td>', 'I like the depth of field on this one.', '2009-06-30 13:48:08.000000', NULL, 1),
(5551003, 801534, 98186, '<td valign="top">Great shot!  I could see this being in an auto magazine.</td>', 'Great shot!  I could see this being in an auto magazine.', '2009-06-30 13:49:52.000000', NULL, 1),
(5551005, 800874, 83313, '<td valign="top">Sweet car. I''m afraid the location in partial shadow and sun hurts it a toad. Possible that some additional adjustments could help the car stand out from the shadows a bit. <br/> <br/>Your 95K file size also suggests you may have been able to get a little more clarity by using less compression. (I''m a little anal about compression)</td>', 'Sweet car. I''m afraid the location in partial shadow and sun hurts it a toad. Possible that some additional adjustments could help the car stand out from the shadows a bit.  Your 95K file size also suggests you may have been able to get a little more clarity by using less compression. (I''m a little anal about compression)', '2009-06-30 13:52:24.000000', NULL, 1),
(5551007, 800650, 98186, '<td valign="top">An interesting looking old car, and an unfortunate ugly board.  Not bad though.</td>', 'An interesting looking old car, and an unfortunate ugly board.  Not bad though.', '2009-06-30 13:53:15.000000', NULL, 1),
(5551008, 801314, 83313, '<td valign="top">Haven''t I seen this place in the Gas Stations challenge?</td>', 'Haven''t I seen this place in the Gas Stations challenge?', '2009-06-30 13:54:13.000000', NULL, 1),
(5551010, 800416, 83313, '<td valign="top">I like the use of tilt and the way you used the composition to turn the distracting background into an element of the scene.</td>', 'I like the use of tilt and the way you used the composition to turn the distracting background into an element of the scene.', '2009-06-30 13:55:37.000000', NULL, 1),
(5551012, 801687, 98186, '<td valign="top">Cool angle but the shadows could be brighter I think.</td>', 'Cool angle but the shadows could be brighter I think.', '2009-06-30 13:56:15.000000', NULL, 1),
(5551015, 800934, 98186, '<td valign="top">Cool picture.  Beautiful red car and a nice contrasting background that doesn''t distract too much.</td>', 'Cool picture.  Beautiful red car and a nice contrasting background that doesn''t distract too much.', '2009-06-30 13:56:53.000000', NULL, 1),
(5551017, 801244, 35602, '<td valign="top">It is a bit out of focus.  Can''t really tell what is around it either.</td>', 'It is a bit out of focus.  Can''t really tell what is around it either.', '2009-06-30 13:57:07.000000', NULL, 1),
(5551018, 800747, 35602, '<td valign="top">Great colors</td>', 'Great colors', '2009-06-30 13:57:19.000000', NULL, 1),
(5551021, 800652, 83313, '<td valign="top">I like this. The desat leaving just the barest touch of orange really works for it. The nice low perspective removes background clutter. (A method I use as well.) A fave and a nice high vote for this one.</td>', 'I like this. The desat leaving just the barest touch of orange really works for it. The nice low perspective removes background clutter. (A method I use as well.) A fave and a nice high vote for this one.', '2009-06-30 13:58:38.000000', NULL, 1),
(5551022, 801743, 35602, '<td valign="top">Love this.  The moss, the cracked window, just a really great image.</td>', 'Love this.  The moss, the cracked window, just a really great image.', '2009-06-30 13:59:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5551023, 801123, 98186, '<td valign="top">Great colors.  Great exposure too!</td>', 'Great colors.  Great exposure too!', '2009-06-30 13:59:55.000000', NULL, 1),
(5551025, 800188, 35602, '<td valign="top">Very funny composition.</td>', 'Very funny composition.', '2009-06-30 14:00:14.000000', NULL, 1),
(5551026, 800797, 88836, '<td valign="top">really like the use of wide angle</td>', 'really like the use of wide angle', '2009-06-30 14:01:36.000000', NULL, 1),
(5551031, 800790, 83313, '<td valign="top">Image is way too small, but this you have certainly been told that already. White balance may also be a problem, there is a distinct yellowish cast to the scene.<br/> <br/>There is a lot of pixellation visible in this shot, and that is the bigger problem. Your file size of only 41k indicates a highly compressed image and that is what is robbing most of the detail from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (150k for this one)</td>', 'Image is way too small, but this you have certainly been told that already. White balance may also be a problem, there is a distinct yellowish cast to the scene. There is a lot of pixellation visible in this shot, and that is the bigger problem. Your file size of only 41k indicates a highly compressed image and that is what is robbing most of the detail from this image. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (150k for this one)', '2009-06-30 14:05:25.000000', NULL, 1),
(5551077, 801726, 62989, '<td valign="top">Fantastic colour on this one - nice work, 10</td>', 'Fantastic colour on this one - nice work, 10', '2009-06-30 14:28:57.000000', NULL, 1),
(5551079, 800256, 62989, '<td valign="top">I like the pp on this and the slight tilt - good picture - 10</td>', 'I like the pp on this and the slight tilt - good picture - 10', '2009-06-30 14:29:22.000000', NULL, 1),
(5551080, 801691, 62989, '<td valign="top">Definitely the best of the dilapidated ones = 9</td>', 'Definitely the best of the dilapidated ones = 9', '2009-06-30 14:29:46.000000', NULL, 1),
(5551081, 801160, 62989, '<td valign="top">Very stylish - best of the ''straight'' shots, 9</td>', 'Very stylish - best of the ''straight'' shots, 9', '2009-06-30 14:30:10.000000', NULL, 1),
(5551083, 801692, 83313, '<td valign="top">The composition doesn''t seem to work for me, I''m afriad. Leads my eye into that blank sky.</td>', 'The composition doesn''t seem to work for me, I''m afriad. Leads my eye into that blank sky.', '2009-06-30 14:33:49.000000', NULL, 1),
(5551086, 801377, 83313, '<td valign="top">A good enough basic shot, but it''s just plopped in the middle of the frame, so my eye lands there and goes nowhere else.</td>', 'A good enough basic shot, but it''s just plopped in the middle of the frame, so my eye lands there and goes nowhere else.', '2009-06-30 14:35:40.000000', NULL, 1),
(5551087, 800923, 83313, '<td valign="top">Not sure what it is about this, but it is not coming off well for me. Might be that big sign in the middle grabbing my eye instead of the truck, which seems to be hiding in the corner.</td>', 'Not sure what it is about this, but it is not coming off well for me. Might be that big sign in the middle grabbing my eye instead of the truck, which seems to be hiding in the corner.', '2009-06-30 14:38:14.000000', NULL, 1),
(5551093, 801053, 83313, '<td valign="top">In spite of the physical constraints of shooting in a museum (I tried some, and mine were less than outstanding) you nailed some great composition and a sharp detailed shot.</td>', 'In spite of the physical constraints of shooting in a museum (I tried some, and mine were less than outstanding) you nailed some great composition and a sharp detailed shot.', '2009-06-30 14:40:07.000000', NULL, 1),
(5551096, 801123, 83313, '<td valign="top">I''m expecting to see this close to the top.</td>', 'I''m expecting to see this close to the top.', '2009-06-30 14:41:43.000000', NULL, 1),
(5551097, 801646, 83313, '<td valign="top">How do you get it up that little staircase?</td>', 'How do you get it up that little staircase?', '2009-06-30 14:42:50.000000', NULL, 1),
(5551099, 800337, 83313, '<td valign="top">Like the car, exposure and sharpness are perfect, but why cropped so tight that the front and rear are slightly cut off? If I have to crop this tight, I prefer to zoom in more for a detail shot, or compose it differently.</td>', 'Like the car, exposure and sharpness are perfect, but why cropped so tight that the front and rear are slightly cut off? If I have to crop this tight, I prefer to zoom in more for a detail shot, or compose it differently.', '2009-06-30 14:45:23.000000', NULL, 1),
(5551101, 801706, 83313, '<td valign="top">Nice semi-abstract detail. Love these things!</td>', 'Nice semi-abstract detail. Love these things!', '2009-06-30 14:45:49.000000', NULL, 1),
(5551104, 801702, 107943, '<td valign="top">I love it..my favorite!</td>', 'I love it..my favorite!', '2009-06-30 14:51:03.000000', NULL, 1),
(5551107, 800714, 107943, '<td valign="top">I like the colours in your image</td>', 'I like the colours in your image', '2009-06-30 14:52:19.000000', NULL, 1),
(5551108, 800193, 83313, '<td valign="top">A good subject, but I think it could probably benefit from some more adjustments to give it some visual pop. I tried it myself and some quick adjustments really made the detail come out of this. (IMO, your mileage may vary)</td>', 'A good subject, but I think it could probably benefit from some more adjustments to give it some visual pop. I tried it myself and some quick adjustments really made the detail come out of this. (IMO, your mileage may vary)', '2009-06-30 14:52:30.000000', NULL, 1),
(5551109, 801402, 83313, '<td valign="top">I think I like this view just slightly better than the other entry of this same scene from further away. I like them both a lot, however.</td>', 'I think I like this view just slightly better than the other entry of this same scene from further away. I like them both a lot, however.', '2009-06-30 14:53:45.000000', NULL, 1),
(5551111, 800747, 83313, '<td valign="top">Nice, though it might benefit from some more visual pop as well. That''s a personal preference thing, perhaps. I popped it into PSP to see, and applied some levels and an s-curve. Really popped off the page after that. I would have likely rated it a couple of points higher than the 6 I am giving it.</td>', 'Nice, though it might benefit from some more visual pop as well. That''s a personal preference thing, perhaps. I popped it into PSP to see, and applied some levels and an s-curve. Really popped off the page after that. I would have likely rated it a couple of points higher than the 6 I am giving it.', '2009-06-30 14:58:31.000000', NULL, 1),
(5551114, 801669, 83313, '<td valign="top">Nice, though that shrubbery is grabbing my eye, instead of the car. I usually turn down the saturation of the yellow when I have a shot like this.</td>', 'Nice, though that shrubbery is grabbing my eye, instead of the car. I usually turn down the saturation of the yellow when I have a shot like this.', '2009-06-30 15:01:06.000000', NULL, 1),
(5551119, 800186, 83313, '<td valign="top">Way to much JPEG compression. Considering the 30k file size, I am surprised it looks this good, but you can see obvious artifacts through the windows. Compression kills detail. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (150k for this one)</td>', 'Way to much JPEG compression. Considering the 30k file size, I am surprised it looks this good, but you can see obvious artifacts through the windows. Compression kills detail. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit. (150k for this one)', '2009-06-30 15:03:59.000000', NULL, 1),
(5551121, 801732, 83313, '<td valign="top">I guess I have to give this an 8? Good thing it deserves it.</td>', 'I guess I have to give this an 8? Good thing it deserves it.', '2009-06-30 15:04:59.000000', NULL, 1),
(5551145, 800890, 54446, '<td valign="top">If this is a 1967 Chevelle, then I had one of these in 1972.  I guess it''s old enough, but seems like yesterday.</td>', 'If this is a 1967 Chevelle, then I had one of these in 1972.  I guess it''s old enough, but seems like yesterday.', '2009-06-30 15:23:08.000000', NULL, 1),
(5551198, 801220, 108188, '<td valign="top">Good color contrast but I feel as though the photographer "missed" when aiming the camera!  This doesn''t capture the lines of this car.</td>', 'Good color contrast but I feel as though the photographer "missed" when aiming the camera!  This doesn''t capture the lines of this car.', '2009-06-30 16:47:19.000000', NULL, 1),
(5551205, 801687, 108188, '<td valign="top">nice wide angle and perspective.  I would rather see the car fill the frame and eliminate the ground in the foreground.  Still a nice shot</td>', 'nice wide angle and perspective.  I would rather see the car fill the frame and eliminate the ground in the foreground.  Still a nice shot', '2009-06-30 16:52:51.000000', NULL, 1),
(5551206, 800728, 108188, '<td valign="top">The composition throws me in this. what is the primary subject? the car is lost.  The building is blocked. I''m confused.  I''d like to see the car off to the side a bit, filling foreground, go monochrome with high contrast.</td>', 'The composition throws me in this. what is the primary subject? the car is lost.  The building is blocked. I''m confused.  I''d like to see the car off to the side a bit, filling foreground, go monochrome with high contrast.', '2009-06-30 16:55:39.000000', NULL, 1),
(5551208, 801711, 108188, '<td valign="top">The car needs to be the focus of this pic.  Get closer.  Make the sunrise (set?) enhance the car.  let the car fill more of the frame</td>', 'The car needs to be the focus of this pic.  Get closer.  Make the sunrise (set?) enhance the car.  let the car fill more of the frame', '2009-06-30 16:56:58.000000', NULL, 1),
(5551209, 801401, 108188, '<td valign="top">interesting...if you like junk.  technically nice.  sharp clear.  nice color scheme</td>', 'interesting...if you like junk.  technically nice.  sharp clear.  nice color scheme', '2009-06-30 16:57:47.000000', NULL, 1),
(5551211, 801702, 108188, '<td valign="top">I''d like to see this pic straight on with the CHEVROLET at the bottom and focus on the leaves in the grill.  perhaps tint them with color</td>', 'I''d like to see this pic straight on with the CHEVROLET at the bottom and focus on the leaves in the grill.  perhaps tint them with color', '2009-06-30 16:59:04.000000', NULL, 1),
(5551212, 801721, 108188, '<td valign="top">nice car. snapshot pic</td>', 'nice car. snapshot pic', '2009-06-30 16:59:17.000000', NULL, 1),
(5551213, 801591, 108188, '<td valign="top">Last chance gas?  nice pic.  I wonder what it would look like with a wider angle lens and getting a little closer...i.e distort perspective.</td>', 'Last chance gas?  nice pic.  I wonder what it would look like with a wider angle lens and getting a little closer...i.e distort perspective.', '2009-06-30 17:00:49.000000', NULL, 1),
(5551214, 800197, 108188, '<td valign="top">fill the frame more with your subject.  The fence is unimportant</td>', 'fill the frame more with your subject.  The fence is unimportant', '2009-06-30 17:01:40.000000', NULL, 1),
(5551215, 801053, 108188, '<td valign="top">cool car but the photo is boring.</td>', 'cool car but the photo is boring.', '2009-06-30 17:02:05.000000', NULL, 1),
(5551216, 800890, 108188, '<td valign="top">nice color.  Close the hood.</td>', 'nice color.  Close the hood.', '2009-06-30 17:02:43.000000', NULL, 1),
(5551218, 800934, 108188, '<td valign="top">almost like a Ford postcard!  nice</td>', 'almost like a Ford postcard!  nice', '2009-06-30 17:03:26.000000', NULL, 1),
(5551219, 801402, 108188, '<td valign="top">nice</td>', 'nice', '2009-06-30 17:04:12.000000', NULL, 1),
(5551220, 801123, 108188, '<td valign="top">scenic.  too much sky...i.e. nothing space.  cool concept.  Moaybe go sepia or black and white and put a hand tint on the truck in red to highlight it</td>', 'scenic.  too much sky...i.e. nothing space.  cool concept.  Moaybe go sepia or black and white and put a hand tint on the truck in red to highlight it', '2009-06-30 17:05:24.000000', NULL, 1),
(5551226, 800337, 108188, '<td valign="top">get close and get interesting perspectives or get back and get it all.</td>', 'get close and get interesting perspectives or get back and get it all.', '2009-06-30 17:06:32.000000', NULL, 1),
(5551227, 801675, 108188, '<td valign="top">snapshot.  nothing grabs interest</td>', 'snapshot.  nothing grabs interest', '2009-06-30 17:06:56.000000', NULL, 1),
(5551228, 800714, 108188, '<td valign="top">nice.  Love the colors</td>', 'nice.  Love the colors', '2009-06-30 17:07:17.000000', NULL, 1),
(5551233, 801533, 108188, '<td valign="top">I love the flying lady ornament and would have greatly preferred to see that as a focus</td>', 'I love the flying lady ornament and would have greatly preferred to see that as a focus', '2009-06-30 17:10:04.000000', NULL, 1),
