(5551239, 801641, 108188, '<td valign="top">too much sky.  could be cropped landscape and be a better pic.  nice composition on the reflections</td>', 'too much sky.  could be cropped landscape and be a better pic.  nice composition on the reflections', '2009-06-30 17:12:05.000000', NULL, 1),
(5551241, 801534, 108188, '<td valign="top">grill needs light</td>', 'grill needs light', '2009-06-30 17:12:35.000000', NULL, 1),
(5551242, 801160, 61222, '<td valign="top">This is so cool.</td>', 'This is so cool.', '2009-06-30 17:12:53.000000', NULL, 1),
(5551248, 800930, 108188, '<td valign="top">Nice.  The real picture here is the tail light lines. Needs just a slightly different angle to take them down the line.</td>', 'Nice.  The real picture here is the tail light lines. Needs just a slightly different angle to take them down the line.', '2009-06-30 17:14:23.000000', NULL, 1),
(5551249, 801150, 108188, '<td valign="top">focus</td>', 'focus', '2009-06-30 17:14:32.000000', NULL, 1),
(5551252, 801416, 108188, '<td valign="top">nice undercarriage</td>', 'nice undercarriage', '2009-06-30 17:14:54.000000', NULL, 1),
