INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5555902, 800728, 67237, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by gr33nphoto:</b></div><hr/><i> So... it''s prohibited to sharpen the image? Cause that''s the only "filter" I used (used high pass sharpening). hmmz... </i></td></tr></table> <br/> <br/>Gísli, sorry about the dq. It is clear you missunderstood the rules.<br/>I am not an expert but here my two cents to clarify your doubt:<br/>When they say that the ONLY effect filters allowed in BE are Noise and Gassian Blur, they are explicitly forbidding any and all filters that you may find in PS under the "Others" tab, including High Pass. For the purpose of sharpenning under BE rules you have to use any sharpenning filter such as Sharp, USM or the ones that come embeded in the NR filters such as Neat Image, Ninja, Topaz, etc, etc.   As said just my two cents, but you better trust SC only :-)</td>', 'Originally posted by gr33nphoto: So... it''s prohibited to sharpen the image? Cause that''s the only "filter" I used (used high pass sharpening). hmmz...   Gísli, sorry about the dq. It is clear you missunderstood the rules.I am not an expert but here my two cents to clarify your doubt:When they say that the ONLY effect filters allowed in BE are Noise and Gassian Blur, they are explicitly forbidding any and all filters that you may find in PS under the "Others" tab, including High Pass. For the purpose of sharpenning under BE rules you have to use any sharpenning filter such as Sharp, USM or the ones that come embeded in the NR filters such as Neat Image, Ninja, Topaz, etc, etc.   As said just my two cents, but you better trust SC only :-)', '2009-07-02 16:01:17.000000', NULL, 0),
(5555947, 801415, 62727, '<td valign="top">This comment is in response to your forum post.  I was one of the 9 people who gave you an 8.  This really doesn''t look like an ''old'' car, but judging by your title (Pristine) I concluded that it was an older car in beautiful condition.  However, I can still see why you received so many low scores, this car just doesn''t appear old.  Hope this helps some.</td>', 'This comment is in response to your forum post.  I was one of the 9 people who gave you an 8.  This really doesn''t look like an ''old'' car, but judging by your title (Pristine) I concluded that it was an older car in beautiful condition.  However, I can still see why you received so many low scores, this car just doesn''t appear old.  Hope this helps some.', '2009-07-02 16:27:57.000000', NULL, 0),
